export function Cart({ items, discount }: { items: Item[]; discount?: number }) {
  const total = items.reduce((acc, i) => acc + i.cents, 0);
  const discountAmount = total * (discount ?? 0) / 100;
  const finalTotal = total - discountAmount;
  return (
    <ul>
      {items.map((i) => (
        <li key={i.name}>
          {i.name} — {formatPrice(i.cents)}
        </li>
      ))}
      {discount > 0 ? (
        <li key="discount">
          Descuento: -{formatPrice(discountAmount)}
        </li>
      ) : null}
      <li>Total: {formatPrice(finalTotal)}</li>
    </ul>
  );
}

